import numpy as np
from scipy.fft import rfft, irfft, next_fast_len
from reference import Task
import os

# We see some env vars in benchmark.py that we could override, but they are already set.
# Let's just use scipy.fft with workers=-1

class Solver(Task):
    def solve(self, problem, **kwargs):
        x_list = problem["signal_x"]
        y_list = problem["signal_y"]
        s1 = len(x_list)
        s2 = len(y_list)

        mode = problem.get("mode", "full")

        if s1 == 0 or s2 == 0:
            if mode == "full":
                return {"convolution": np.array([])}
            elif mode == "same":
                return {"convolution": np.array([])}
            elif mode == "valid":
                return {"convolution": np.array([])}

        shape = s1 + s2 - 1
        fshape = next_fast_len(shape, True)

        x = np.fromiter(x_list, dtype=float, count=s1)
        y = np.fromiter(y_list, dtype=float, count=s2)

        sp1 = rfft(x, fshape, workers=-1, overwrite_x=True)
        sp2 = rfft(y, fshape, workers=-1, overwrite_x=True)
        np.multiply(sp1, sp2, out=sp1)
        ret = irfft(sp1, fshape, workers=-1, overwrite_x=True)

        if mode == "full":
            return {"convolution": ret[:shape]}
        elif mode == "same":
            start = (s2 - 1) // 2
            return {"convolution": ret[start:start+s1]}
        elif mode == "valid":
            start = min(s1, s2) - 1
            end = max(s1, s2)
            return {"convolution": ret[start:end]}

