import numpy as np
from scipy import sparse
from scipy.sparse.linalg import expm, splu
import scipy.sparse.linalg._matfuncs as matfuncs

# Monkey patch _solve_P_Q
original_solve_P_Q = matfuncs._solve_P_Q

def fast_solve_P_Q(U, V, structure=None):
    P = U + V
    Q = -U + V
    if sparse.issparse(U) or matfuncs.is_pydata_spmatrix(U):
        # Use splu instead of spsolve
        lu = splu(Q.tocsc())
        res = lu.solve(P.toarray())
        return sparse.csc_matrix(res)
    else:
        return original_solve_P_Q(U, V, structure)

class Solver:
    def __init__(self, **kwargs):
        pass

    def solve(self, problem: dict[str, sparse.spmatrix]) -> sparse.spmatrix:
        A = problem["matrix"]

        # We can temporarily patch _solve_P_Q in scipy.sparse.linalg._matfuncs
        matfuncs._solve_P_Q = fast_solve_P_Q
        try:
            res = expm(A)
        finally:
            matfuncs._solve_P_Q = original_solve_P_Q

        return res
